 "Arpa": "Arpa",
 "<span style=\"font-family:'Courier New', Courier, monospace;font-size:16px;letter-spacing:1px;color:#c0392b\">CORDÓFONO</span><br><b>Arpa</b><br><span style=\"font-size:21px;color:#6d5c45\">Vibran cuerdas tensas</span>": "<span style=\"font-family:'Courier New', Courier, monospace;font-size:16px;letter-spacing:1px;color:#c0392b\">CORDOFONO</span><br><b>Arpa</b><br><span style=\"font-size:21px;color:#6d5c45\">Vibrano corde tese</span>",
 "Flauta dulce": "Flauto dolce",
